package com.atlasiq.enterprise;
import jakarta.enterprise.context.ApplicationScoped;import java.time.Instant;import java.util.*;
@ApplicationScoped public class OrganizationService {private final EnterpriseStore store;public OrganizationService(EnterpriseStore s){store=s;}public Organization createOrg(String name){return store.createOrg(name);}public Workspace createWorkspace(String org,String name){return store.createWorkspace(org,name);}public List<Workspace> workspaces(String org){return store.workspaces(org);}public void addMembership(String org,String ws,String subject,String role){store.membership(org,ws,subject,role);}public record Organization(String id,String name,Instant createdAt){}public record Workspace(String id,String organizationId,String name,Instant createdAt){}}
